import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import api from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Truck, CheckCircle2, Package, ChefHat, Download, XCircle, Clock3, MapPin, Phone, CreditCard } from "lucide-react";

const STAGES = [
  { key: "placed", label: "Order Placed", icon: Package },
  { key: "confirmed", label: "Confirmed", icon: ChefHat },
  { key: "rider_assigned", label: "Rider Assigned", icon: Truck },
  { key: "delivered", label: "Delivered", icon: CheckCircle2 },
];

const formatDateTime = (value) => {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString();
};

export default function OrderDetail() {
  const { id } = useParams();
  const [o, setO] = useState(null);

  useEffect(() => {
    let interval;

    const fetchOrder = async () => {
      try {
        const res = await api.get(`/orders/${id}`);
        setO(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchOrder();
    interval = setInterval(fetchOrder, 5000);

    return () => clearInterval(interval);
  }, [id]);

  if (!o) return <div className="py-20 text-center text-[#5C4A3D]">Loading your order details...</div>;

  const idx = STAGES.findIndex((s) => s.key === o.status);
  const progressPercent = o.status === "cancelled" ? 0 : Math.max(10, ((idx + 1) / STAGES.length) * 100);

  const invoice = () => {
    const cancellationNote = o.cancellation_reason ? `<p><b>Cancellation Reason:</b> ${o.cancellation_reason}</p>` : "";
    const html = `
<html><head><title>Invoice ${o.order_no}</title>
<style>body{font-family:Arial;padding:40px;max-width:700px;margin:auto;}h1{color:#D97706}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left}</style>
</head><body><h1>SLV Bakery</h1><p><b>Invoice:</b> ${o.order_no}<br/><b>Order Date:</b> ${formatDateTime(o.created_at)}<br/><b>Delivered Date:</b> ${o.status === "delivered" && o.delivered_at ? formatDateTime(o.delivered_at) : "—"}<br/><b>Status:</b> ${o.status}<br/><b>Customer:</b> ${o.user_name} (${o.user_email})<br/><b>Phone:</b> ${o.phone}<br/><b>Address:</b> ${o.address}</p>
${cancellationNote}
<table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>
${o.items.map((i) => `<tr><td>${i.name}</td><td>${i.quantity}</td><td>₹${i.price}</td><td>₹${(i.price * i.quantity).toFixed(0)}</td></tr>`).join("")}
</tbody></table><br/>
<p>Subtotal: ₹${o.subtotal}<br/>Platform: ₹${o.platform_fee}<br/>Delivery: ₹${o.delivery_charge}<br/>Packaging: ₹${o.packaging}<br/>Discount: -₹${o.discount}<br/><b>Grand Total: ₹${o.total}</b></p>
<p>Payment: ${o.payment_method}</p></body></html>`;
    const w = window.open("", "_blank");
    w.document.write(html);
    w.document.close();
    w.print();
  };

  return (
    <div className="min-h-screen bg-[linear-gradient(135deg,#fffaf2_0%,#fffdf8_100%)] py-6 md:py-10">
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .fade-in { animation: fadeIn 0.45s ease-out both; }
      `}</style>

      <div className="max-w-5xl mx-auto px-4" data-testid="order-detail">
        <div className="fade-in mb-6 rounded-[28px] border border-[#E6DFD5] bg-gradient-to-br from-[#FFF8EE] via-white to-[#FFF2DA] p-6 shadow-[0_20px_60px_-20px_rgba(217,119,6,0.30)]">
          <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
            <div>
              <div className="uppercase-tracked text-xs text-[#D97706] mb-2">Order Overview</div>
              <h1 className="font-display text-2xl md:text-3xl font-bold text-[#2D1E16]">{o.order_no}</h1>
              <p className="mt-2 text-sm text-[#5C4A3D]">Track your order in real time and review every detail in one place.</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <span className="rounded-full bg-[#D97706] px-3 py-1 text-sm font-semibold text-white">
                {o.status === "cancelled" ? "Cancelled" : "In Progress"}
              </span>
              <Button onClick={invoice} variant="outline" className="rounded-full border-[#D97706] text-[#D97706] hover:bg-[#FFF4E5]" data-testid="download-invoice">
                <Download className="mr-1 h-4 w-4" /> Invoice
              </Button>
            </div>
          </div>
        </div>

        <div className="fade-in mb-6 rounded-[24px] border border-[#E6DFD5] bg-white p-6 shadow-sm transition-all duration-300 hover:shadow-lg">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h3 className="font-semibold text-[#2D1E16]">Order Tracking</h3>
              <p className="text-sm text-[#5C4A3D]">Your order is moving smoothly through each milestone.</p>
            </div>
            <div className="text-sm font-medium text-[#D97706]">{o.status === "cancelled" ? "Cancelled" : `${Math.round(progressPercent)}% complete`}</div>
          </div>

          {o.status === "cancelled" ? (
            <div className="flex flex-col items-center justify-center rounded-2xl bg-red-50 px-4 py-10 text-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-full bg-red-100">
                <XCircle className="h-8 w-8 text-red-600" />
              </div>
              <h4 className="mt-4 text-lg font-semibold text-red-600">Order Cancelled</h4>
              <p className="mt-2 max-w-md text-sm text-gray-600">This order has been cancelled and will not be processed further.</p>
            </div>
          ) : (
            <>
              <div className="mb-4 h-2 rounded-full bg-[#F3EEE4]">
                <div className="h-2 rounded-full bg-gradient-to-r from-[#D97706] to-[#F59E0B] transition-all duration-500" style={{ width: `${progressPercent}%` }} />
              </div>

              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                {STAGES.map((s, i) => {
                  const active = i <= idx;
                  const Icon = s.icon;

                  return (
                    <div key={s.key} className={`rounded-2xl border p-3 text-center transition-all duration-300 ${active ? "border-[#F4C58A] bg-[#FFF8EE] shadow-sm" : "border-[#F3EEE4] bg-white"}`}>
                      <div className={`mx-auto flex h-11 w-11 items-center justify-center rounded-full transition-all duration-300 ${active ? "bg-[#D97706] text-white" : "bg-[#FBF5EA] text-[#5C4A3D]"}`}>
                        <Icon className="h-5 w-5" />
                      </div>
                      <div className={`mt-3 text-sm font-semibold ${active ? "text-[#2D1E16]" : "text-[#5C4A3D]"}`}>{s.label}</div>
                    </div>
                  );
                })}
              </div>

              {(o.rider_name || o.rider_phone) && (
                <div className="mt-4 rounded-2xl bg-[#FBF5EA] px-4 py-3 text-sm text-[#5C4A3D]">
                  {o.rider_name && <div>Rider: <b>{o.rider_name}</b></div>}
                  {o.rider_phone && <div>Rider Phone: <b>{o.rider_phone}</b></div>}
                </div>
              )}
            </>
          )}
        </div>

        <div className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
          <div className="fade-in rounded-[24px] border border-[#E6DFD5] bg-white p-6 shadow-sm transition-all duration-300 hover:shadow-lg">
            <div className="mb-4 flex items-center justify-between">
              <h3 className="font-semibold text-[#2D1E16]">Items Ordered</h3>
              <span className="rounded-full bg-[#FFF4E5] px-3 py-1 text-xs font-semibold text-[#D97706]">{o.items.length} item(s)</span>
            </div>

            <div className="space-y-2">
              {o.items.map((i, k) => (
                <div key={k} className="flex items-center justify-between rounded-2xl bg-[#FFFDF9] px-4 py-3 transition-all duration-200 hover:bg-[#FFF8EE]">
                  <div>
                    <div className="font-medium text-[#2D1E16]">{i.name}</div>
                    <div className="text-sm text-[#5C4A3D]">Qty: {i.quantity}</div>
                  </div>
                  <div className="font-semibold text-[#2D1E16]">₹{(i.price * i.quantity).toFixed(0)}</div>
                </div>
              ))}
            </div>
          </div>

          <div className="fade-in rounded-[24px] border border-[#E6DFD5] bg-white p-6 shadow-sm transition-all duration-300 hover:shadow-lg">
            <h3 className="font-semibold text-[#2D1E16]">Payment & Delivery</h3>
            <div className="mt-4 space-y-3 text-sm text-[#5C4A3D]">
              <div className="flex items-start gap-2"><Clock3 className="mt-0.5 h-4 w-4 text-[#D97706]" /><span>Ordered: {formatDateTime(o.created_at)}</span></div>
              {o.status === "delivered" && o.delivered_at && <div className="flex items-start gap-2"><CheckCircle2 className="mt-0.5 h-4 w-4 text-[#D97706]" /><span>Delivered: {formatDateTime(o.delivered_at)}</span></div>}
              {o.status === "cancelled" && o.cancellation_reason && <div className="flex items-start gap-2"><XCircle className="mt-0.5 h-4 w-4 text-red-500" /><span className="text-red-600">Cancellation reason: {o.cancellation_reason}</span></div>}
              <div className="flex items-start gap-2"><MapPin className="mt-0.5 h-4 w-4 text-[#D97706]" /><span>Address: {o.address}</span></div>
              <div className="flex items-start gap-2"><Phone className="mt-0.5 h-4 w-4 text-[#D97706]" /><span>Phone: {o.phone}</span></div>
              <div className="flex items-start gap-2"><CreditCard className="mt-0.5 h-4 w-4 text-[#D97706]" /><span>Payment: {o.payment_method}</span></div>
            </div>

            <div className="mt-5 rounded-2xl bg-[#FBF5EA] p-4 text-sm">
              <div className="flex justify-between"><span>Subtotal</span><span>₹{o.subtotal}</span></div>
              <div className="flex justify-between"><span>Platform Fee</span><span>₹{o.platform_fee}</span></div>
              <div className="flex justify-between"><span>Delivery</span><span>₹{o.delivery_charge}</span></div>
              <div className="flex justify-between"><span>Packaging</span><span>₹{o.packaging}</span></div>
              {o.discount > 0 && <div className="flex justify-between text-[#4D7C0F]"><span>Discount</span><span>-₹{o.discount}</span></div>}
              <div className="mt-3 flex justify-between border-t border-[#E6DFD5] pt-2 text-base font-bold text-[#2D1E16]"><span>Total</span><span>₹{o.total}</span></div>
            </div>
          </div>
        </div>

        <div className="mt-5">
          <Link to="/my-orders" className="inline-flex items-center text-sm font-medium text-[#D97706] transition-colors duration-200 hover:text-[#B45309]">← Back to orders</Link>
        </div>
      </div>
    </div>
  );
}
